packaging.tags._linux_platforms:
def _linux_platforms(is_32bit: bool = _32_BIT_INTERPRETER) -> Iterator[str]:
    linux = _normalize_string(sysconfig.get_platform())
    if not linux.startswith('linux_'):
        yield linux
        return
    if is_32bit:
        if linux == 'linux_x86_64':
            linux = 'linux_i686'
        elif linux == 'linux_aarch64':
            linux = 'linux_armv8l'
    (_, arch) = linux.split('_', 1)
    archs = {'armv8l': ['armv8l', 'armv7l']}.get(arch, [arch])
    yield from _manylinux.platform_tags(archs)
    yield from _musllinux.platform_tags(archs)
    for arch in archs:
        yield f'linux_{arch}'

packaging.tags.mac_platforms:
def mac_platforms(version: AppleVersion | None = None, arch: str | None = None) -> Iterator[str]:
    """
    Yields the :attr:`~Tag.platform` tags for macOS.

    The `version` parameter is a two-item tuple specifying the macOS version to
    generate platform tags for. The `arch` parameter is the CPU architecture to
    generate platform tags for. Both parameters default to the appropriate value
    for the current system.

    :param tuple version: A two-item tuple representing the version of macOS.
                          Defaults to the current system's version.
    :param str arch: The CPU architecture. Defaults to the architecture of the
                     current system, e.g. ``"x86_64"``.

    .. note::
        Equivalent support for the other major platforms is purposefully not
        provided:

        - On Windows, platform compatibility is statically specified
        - On Linux, code must be run on the system itself to determine
          compatibility
    """
    (version_str, _, cpu_arch) = platform.mac_ver()
    if version is None:
        version = cast('AppleVersion', tuple(map(int, version_str.split('.')[:2])))
        if version == (10, 16):
            version_str = subprocess.run([sys.executable, '-sS', '-c', 'import platform; print(platform.mac_ver()[0])'], check=True, env={'SYSTEM_VERSION_COMPAT': '0'}, stdout=subprocess.PIPE, text=True).stdout
            version = cast('AppleVersion', tuple(map(int, version_str.split('.')[:2])))
    if arch is None:
        arch = _mac_arch(cpu_arch)
    if (10, 0) <= version < (11, 0):
        major_version = 10
        for minor_version in range(version[1], -1, -1):
            compat_version = (major_version, minor_version)
            binary_formats = _mac_binary_formats(compat_version, arch)
            for binary_format in binary_formats:
                yield f'macosx_{major_version}_{minor_version}_{binary_format}'
    if version >= (11, 0):
        minor_version = 0
        for major_version in range(version[0], 10, -1):
            compat_version = (major_version, minor_version)
            binary_formats = _mac_binary_formats(compat_version, arch)
            for binary_format in binary_formats:
                yield f'macosx_{major_version}_{minor_version}_{binary_format}'
    if version >= (11, 0):
        major_version = 10
        if arch == 'x86_64':
            for minor_version in range(16, 3, -1):
                compat_version = (major_version, minor_version)
                binary_formats = _mac_binary_formats(compat_version, arch)
                for binary_format in binary_formats:
                    yield f'macosx_{major_version}_{minor_version}_{binary_format}'
        else:
            for minor_version in range(16, 3, -1):
                compat_version = (major_version, minor_version)
                binary_format = 'universal2'
                yield f'macosx_{major_version}_{minor_version}_{binary_format}'

packaging.tags._emscripten_platforms:
def _emscripten_platforms() -> Iterator[str]:
    pyemscripten_platform_version = sysconfig.get_config_var('PYEMSCRIPTEN_PLATFORM_VERSION')
    if pyemscripten_platform_version:
        yield f'pyemscripten_{pyemscripten_platform_version}_wasm32'
    yield from _generic_platforms()

packaging.tags.platform_tags:
def platform_tags() -> Iterator[str]:
    """
    Yields the :attr:`~Tag.platform` tags for the running interpreter.
    """
    if platform.system() == 'Darwin':
        return mac_platforms()
    elif platform.system() == 'iOS':
        return ios_platforms()
    elif platform.system() == 'Android':
        return android_platforms()
    elif platform.system() == 'Linux':
        return _linux_platforms()
    elif platform.system() == 'Emscripten':
        return _emscripten_platforms()
    else:
        return _generic_platforms()

packaging._manylinux.platform_tags:
def platform_tags(archs: Sequence[str]) -> Iterator[str]:
    """Generate manylinux tags compatible to the current platform.

    :param archs: Sequence of compatible architectures.
        The first one shall be the closest to the actual architecture and be the part of
        platform tag after the ``linux_`` prefix, e.g. ``x86_64``.
        The ``linux_`` prefix is assumed as a prerequisite for the current platform to
        be manylinux-compatible.

    :returns: An iterator of compatible manylinux tags.
    """
    if not _have_compatible_abi(sys.executable, archs):
        return
    too_old_glibc2 = _GLibCVersion(2, 16)
    if set(archs) & {'x86_64', 'i686'}:
        too_old_glibc2 = _GLibCVersion(2, 4)
    current_glibc = _GLibCVersion(*_get_glibc_version())
    glibc_max_list = [current_glibc]
    for glibc_major in range(current_glibc.major - 1, 1, -1):
        glibc_minor = _LAST_GLIBC_MINOR[glibc_major]
        glibc_max_list.append(_GLibCVersion(glibc_major, glibc_minor))
    for arch in archs:
        for glibc_max in glibc_max_list:
            if glibc_max.major == too_old_glibc2.major:
                min_minor = too_old_glibc2.minor
            else:
                min_minor = -1
            for glibc_minor in range(glibc_max.minor, min_minor, -1):
                glibc_version = _GLibCVersion(glibc_max.major, glibc_minor)
                if _is_compatible(arch, glibc_version):
                    yield 'manylinux_{}_{}_{}'.format(*glibc_version, arch)
                    if legacy_tag := _LEGACY_MANYLINUX_MAP.get(glibc_version):
                        yield f'{legacy_tag}_{arch}'

packaging.tags._cpython_abis:
def _cpython_abis(py_version: PythonVersion, warn: bool = False) -> list[str]:
    py_version = tuple(py_version)
    abis = []
    version = _version_nodot(py_version[:2])
    threading = debug = pymalloc = ucs4 = ''
    with_debug = _get_config_var('Py_DEBUG', warn)
    has_refcount = hasattr(sys, 'gettotalrefcount')
    has_ext = '_d.pyd' in EXTENSION_SUFFIXES
    if (with_debug or (with_debug is None and ((has_refcount or has_ext)))):
        debug = 'd'
    if (py_version >= (3, 13) and _get_config_var('Py_GIL_DISABLED', warn)):
        threading = 't'
    if py_version < (3, 8):
        with_pymalloc = _get_config_var('WITH_PYMALLOC', warn)
        if (with_pymalloc or with_pymalloc is None):
            pymalloc = 'm'
        if py_version < (3, 3):
            unicode_size = _get_config_var('Py_UNICODE_SIZE', warn)
            if (unicode_size == 4 or (unicode_size is None and sys.maxunicode == 1114111)):
                ucs4 = 'u'
    elif debug:
        abis.append(f'cp{version}{threading}')
    abis.insert(0, f'cp{version}{threading}{debug}{pymalloc}{ucs4}')
    return abis

packaging.tags._generic_abi:
def _generic_abi() -> list[str]:
    """
    Return the ABI tag based on EXT_SUFFIX.
    """
    ext_suffix = _get_config_var('EXT_SUFFIX', warn=True)
    if (not isinstance(ext_suffix, str) or ext_suffix[0] != '.'):
        raise SystemError("invalid sysconfig.get_config_var('EXT_SUFFIX')")
    parts = ext_suffix.split('.')
    if len(parts) < 3:
        return _cpython_abis(sys.version_info[:2])
    soabi = parts[1]
    if soabi.startswith('cpython'):
        abi = 'cp' + soabi.split('-')[1]
    elif soabi.startswith('cp'):
        abi = soabi.split('-')[0]
    elif soabi.startswith('pypy'):
        abi = '-'.join(soabi.split('-')[:2])
    elif soabi.startswith('graalpy'):
        abi = '-'.join(soabi.split('-')[:3])
    elif soabi:
        abi = soabi
    else:
        return []
    return [_normalize_string(abi)]
